  "InviteResult": {"type": "object", "required": ["created", "skipped"], "properties": {"created": {"type": "integer", "description": "new auth.pending_users rows created from this list"}, "skipped": {"type": "integer", "description": "members already pending/invited, or undeliverable, so left untouched"}}},
  "RotateKeyResult": {"type": "object", "required": ["public_key"], "properties": {"public_key": {"type": "string", "description": "the list's NEW embed key. The old key stops working immediately — any page still embedding it must be updated."}}},
