  "ChatStreamEvent": {"description": "One event in the SSE chat stream. The SSE `event:` name carries the discriminator (`open` | `token` | `tool_call_started` | `tool_call_completed` | `done` | `error`); the JSON `data:` payload is one of the shapes below.", "oneOf": [{"title": "ChatTokenEvent", "type": "object", "description": "token — a chunk of streamed assistant text", "required": ["text"], "properties": {"text": {"type": "string"}}}, {"title": "ChatToolCallStartedEvent", "type": "object", "description": "tool_call_started — the model invoked a tool", "required": ["name", "arguments"], "properties": {"name": {"type": "string"}, "arguments": {"type": "string", "description": "JSON-encoded tool arguments"}}}, {"title": "ChatToolCallCompletedEvent", "type": "object", "description": "tool_call_completed — a tool finished", "required": ["name", "ok", "result"], "properties": {"name": {"type": "string"}, "ok": {"type": "boolean"}, "result": {"type": "string", "description": "JSON-encoded tool result"}}}, {"title": "ChatDoneEvent", "type": "object", "description": "done — the turn completed (empty payload)"}, {"title": "ChatErrorEvent", "type": "object", "description": "error — the turn failed; the message explains why (HTTP stays 200)", "required": ["message"], "properties": {"message": {"type": "string"}}}]},
  "ChatLiveEvent": {"type": "object", "description": "The `data` of an event on GET /chat/stream. Which fields are present depends on the SSE event name (see the route); every chat event carries `chatId`.", "properties": {"chat_id": {"type": "string"}, "seq": {"type": "integer", "description": "`message`, `message_updated`"}, "participant_id": {"type": "string", "description": "`typing`"}, "state": {"type": "string", "enum": ["start", "stop"], "description": "`typing`"}, "expires_at": {"type": "string", "description": "`typing` — ISO time the indicator lapses"}, "added": {"type": "array", "items": {"type": "string"}, "description": "`participants_changed` (participant ids), `chats_changed` (chat ids)"}, "removed": {"type": "array", "items": {"type": "string"}, "description": "`participants_changed` (participant ids), `chats_changed` (chat ids)"}, "chat_ids": {"type": "array", "items": {"type": "string"}, "description": "`ready`"}}},
  "DmMessage": {"type": "object", "description": "One direct message. Also the payload of a `message` event on the DM SSE stream.", "required": ["id", "chat_id", "sender_participant_id", "sender_user_id", "seq", "role", "body", "state", "date_sent"], "properties": {"id": {"type": "string"}, "chat_id": {"type": "string", "maxLength": 36}, "sender_participant_id": {"type": "string", "nullable": true}, "sender_user_id": {"type": "string"}, "seq": {"type": "integer", "description": "Per-chat monotonic sequence; the stream cursor"}, "role": {"type": "string"}, "body": {"type": "string"}, "state": {"type": "string"}, "date_sent": {"type": "string"}}},
