  "DmChatSummary": {"type": "object", "required": ["chat_id", "other_user_id", "last_message", "unread_count"], "properties": {"chat_id": {"type": "string", "maxLength": 36}, "other_user_id": {"type": "string"}, "last_message": {"$ref": "#/components/schemas/DmMessagePreview"}, "unread_count": {"type": "integer"}}},
  "DmChatList": {"type": "object", "required": ["chats", "total", "page", "page_size"], "properties": {"chats": {"type": "array", "items": {"$ref": "#/components/schemas/DmChatSummary"}}, "total": {"type": "integer"}, "page": {"type": "integer"}, "page_size": {"type": "integer"}}},
