  "Chat": {"type": "object", "required": ["id", "type", "definition_id", "name", "photo_storage_key", "created_by_user_id", "created", "updated", "participants"], "properties": {"id": {"type": "string"}, "type": {"type": "string", "enum": ["dm", "group"]}, "definition_id": {"type": "string", "description": "The definition the chat follows; a DM reports the built-in `direct`’s id"}, "name": {"type": "string"}, "photo_storage_key": {"type": "string", "nullable": true}, "created_by_user_id": {"type": "string", "nullable": true}, "created": {"type": "integer", "description": "Unix timestamp, in seconds."}, "updated": {"type": "integer", "description": "Unix timestamp, in seconds."}, "participants": {"type": "array", "description": "Joined participants, longest-standing first", "items": {"$ref": "#/components/schemas/ChatParticipant"}}}},
