  "ChatList": {"type": "object", "required": ["chats", "total", "page", "page_size"], "properties": {"chats": {"type": "array", "items": {"$ref": "#/components/schemas/ChatInboxEntry"}}, "total": {"type": "integer"}, "page": {"type": "integer"}, "page_size": {"type": "integer"}}},
