  "ChatCreateResult": {"type": "object", "required": ["chat", "skipped_persona_ids"], "properties": {"chat": {"$ref": "#/components/schemas/Chat"}, "skipped_persona_ids": {"type": "array", "items": {"type": "string"}, "description": "The definition’s own personas that were not seated because they no longer exist"}}},
