  "ChatTypingRequest": {"type": "object", "required": ["state"], "properties": {"state": {"type": "string", "enum": ["start", "stop"]}}},
  "ChatPersonaReplyEvent": {"type": "object", "description": "The `data` of an event on the persona-reply stream of POST /chat/chats/{id}/messages. The SSE event name discriminates (see the route): `open` carries `message`; `persona_start` carries `participantId` and `personaId`; `message` carries `participantId` and `message`; every turn event (`token`, `tool_call_started`, `tool_call_completed`, `status`, `award`, `done`, `ended`, `error`) carries its own fields (see ChatStreamEvent) plus `participantId`.", "properties": {"participant_id": {"type": "string", "description": "The replying persona’s participant row id"}, "persona_id": {"type": "string", "description": "`persona_start`"}, "message": {"$ref": "#/components/schemas/DmMessage"}}},
  "CommunicationSettings": {"type": "object", "required": ["dm_audience_mask", "presence_audience_mask", "appear_offline"], "properties": {"dm_audience_mask": {"type": "integer", "minimum": 0, "description": "AUDIENCE bitmask of who may DM the user (0 = nobody; default PUBLIC|HUB = 3)"}, "presence_audience_mask": {"type": "integer", "minimum": 0, "description": "AUDIENCE bitmask of who may see the user presence (0 = nobody; default PUBLIC|HUB = 3)"}, "appear_offline": {"type": "boolean", "description": "When true, presence is hidden from EVERYONE regardless of the mask"}}},
  "AppearanceSettings": {"type": "object", "required": ["prefs"], "properties": {"prefs": {"type": "object", "properties": {"color_mode": {"type": "string", "enum": ["auto", "light", "dark"], "description": "The user's colour scheme; 'auto' follows the operating system"}, "reduce_motion": {"type": "string", "enum": ["auto", "on", "off"]}, "contrast": {"type": "string", "enum": ["default", "high", "extra-high"]}, "text_size": {"type": "string", "enum": ["default", "small", "large", "extra-large"]}, "spacing": {"type": "string", "enum": ["compact", "comfortable", "spacious"]}, "focus_outlines": {"type": "boolean"}, "underline_links": {"type": "boolean"}}, "description": "Empty object when the user has never saved a preference (client defaults apply)"}}},
  "WorkspacePrefs": {"type": "object", "required": ["prefs"], "properties": {"prefs": {"type": "object", "properties": {"slug": {"type": "string", "description": "The workspace the user's /home chooser last landed on (a workspace slug)"}}, "description": "Empty object when the user has never chosen a workspace (the client falls back to their personal one)"}}},
  "GamificationLevel": {"type": "object", "required": ["name", "min_points", "sort_order"], "properties": {"name": {"type": "string"}, "min_points": {"type": "integer", "description": "Inclusive point floor for this rung"}, "sort_order": {"type": "integer"}, "subject_type": {"type": "string", "nullable": true, "description": "NULL = applies to any subject kind"}}},
