  "GamificationRealmBadge": {"type": "object", "required": ["id", "name", "description", "icon", "point_value"], "properties": {"id": {"type": "string"}, "name": {"type": "string"}, "description": {"type": "string"}, "icon": {"type": "string"}, "stat_key": {"type": "string", "nullable": true, "description": "The stat the rule watches"}, "comparator": {"type": "string", "nullable": true, "enum": [">=", ">", "=", null]}, "threshold": {"type": "integer", "nullable": true}, "badge_line": {"type": "string", "nullable": true, "description": "Groups the tiers of one line"}, "tier": {"type": "string", "nullable": true, "enum": ["none", "bronze", "silver", "gold", "platinum", null]}, "point_value": {"type": "integer", "description": "XP granted when earned"}, "hidden": {"type": "boolean"}, "active": {"type": "boolean"}, "subject_type": {"type": "string", "nullable": true}, "ecosystem_id": {"type": "string", "nullable": true, "description": "NULL = platform default; else the realm"}}},
  "GamificationCatalogBadge": {"allOf": [{"$ref": "#/components/schemas/GamificationRealmBadge"}, {"type": "object", "required": ["source"], "properties": {"source": {"type": "string", "enum": ["default", "realm"], "description": "'realm' when a realm row shadows the same-slot default"}}}]},
  "GamificationCatalogLevel": {"type": "object", "required": ["name", "min_points", "source"], "properties": {"name": {"type": "string"}, "min_points": {"type": "integer"}, "source": {"type": "string", "enum": ["default", "realm"]}}},
