  "GamificationRealmBadgeInput": {"type": "object", "required": ["name", "description", "icon", "stat_key", "threshold", "badge_line", "tier", "point_value"], "properties": {"name": {"type": "string"}, "description": {"type": "string"}, "icon": {"type": "string"}, "stat_key": {"type": "string"}, "comparator": {"type": "string", "enum": [">=", ">", "="], "default": ">="}, "threshold": {"type": "integer", "minimum": 0}, "badge_line": {"type": "string"}, "tier": {"type": "string", "enum": ["none", "bronze", "silver", "gold", "platinum"]}, "point_value": {"type": "integer", "minimum": 0}, "hidden": {"type": "boolean", "default": false}}},
