  "GamificationRealmEventType": {"type": "object", "required": ["id", "ecosystem_id", "name", "stat_key"], "properties": {"id": {"type": "string"}, "ecosystem_id": {"type": "string"}, "name": {"type": "string", "description": "The custom event_type key"}, "stat_key": {"type": "string", "description": "The gamification stat this event bumps"}, "created": {"type": "integer", "description": "Unix timestamp, in seconds."}, "updated": {"type": "integer", "description": "Unix timestamp, in seconds."}}},
