  "MarkdownDocument": {"type": "object", "required": ["id", "ecosystem_id", "owner_kind", "owner_id", "title", "content", "content_hash", "size_bytes", "current_version", "tags", "visibility", "stage", "kind", "created", "updated", "is_deleted"], "properties": {"id": {"type": "string"}, "author_kind": {"type": "string", "nullable": true, "enum": ["customer", "application", "persona"], "description": "Kind of principal that created the doc (public routes key on a customer author); null when nobody did (a storage token)."}, "author_id": {"type": "string", "nullable": true, "description": "Id of that principal."}, "ecosystem_id": {"type": "string", "description": "Ecosystem (tenant) id."}, "owner_kind": {"type": "string", "enum": ["customer", "organization"], "description": "The kind of principal that OWNS the doc (what access scopes by)."}, "owner_id": {"type": "string", "description": "The owning principal (customer or organization id); server-stamped from the verified ?workspace= scope, else the creator."}, "deleted_at": {"type": "string", "nullable": true}, "title": {"type": "string", "description": "Server-derived, read-only: the frontmatter `title` then `name`, else the first non-empty line of the body (frontmatter and code fences ignored, leading markdown syntax stripped), else 'Untitled'. Capped at 500 characters."}, "content": {"type": "string", "description": "Full raw markdown, byte-exact."}, "frontmatter": {"type": "object", "additionalProperties": true, "nullable": true}, "category": {"type": "string", "nullable": true, "description": "Optional classification label."}, "tags": {"type": "array", "items": {"type": "string"}, "description": "Tag set (defaults to [])."}, "visibility": {"type": "string", "enum": ["private", "public"], "description": "Publication state: 'public' is readable on the public surface, 'private' is a draft."}, "stage": {"type": "string", "enum": ["draft", "final"], "description": "Editorial stage: 'draft' is editable; 'final' is immutable (content edits + version writes are rejected)."}, "kind": {"type": "string", "enum": ["paper", "research"], "description": "Document kind: 'paper' (ordinary) or 'research' (AI-ingested, carries an adh_source frontmatter key)."}, "public_route": {"type": "string", "nullable": true, "description": "Public route slug (non-null iff visibility='public'); unique per author."}, "content_hash": {"type": "string", "description": "SHA-256 hex of content (ETag)."}, "size_bytes": {"type": "integer"}, "current_version": {"type": "integer", "description": "The current revision number (incremented on every edit)."}, "latest_version_id": {"type": "string", "nullable": true}, "created": {"type": "integer", "description": "Unix timestamp, in seconds."}, "updated": {"type": "integer", "description": "Unix timestamp, in seconds."}, "is_deleted": {"type": "boolean"}}},
  "MarkdownDocumentSummary": {"type": "object", "required": ["id", "title", "excerpt", "content_hash", "size_bytes", "current_version", "tags", "visibility", "stage", "kind", "created", "updated"], "properties": {"id": {"type": "string"}, "title": {"type": "string", "description": "Server-derived, read-only: the frontmatter `title` then `name`, else the first non-empty line of the body (frontmatter and code fences ignored, leading markdown syntax stripped), else 'Untitled'. Capped at 500 characters."}, "excerpt": {"type": "string", "description": "Server-derived, read-only preview: up to 4 body lines FOLLOWING the title line, newline-separated, each capped at 160 characters and stripped of leading markdown syntax. Empty when the body holds nothing past its title. Exists because this projection carries no `content` — it is what lets a list render a preview without fetching every document whole."}, "frontmatter": {"type": "object", "additionalProperties": true, "nullable": true}, "category": {"type": "string", "nullable": true}, "tags": {"type": "array", "items": {"type": "string"}}, "visibility": {"type": "string", "enum": ["private", "public"]}, "stage": {"type": "string", "enum": ["draft", "final"]}, "kind": {"type": "string", "enum": ["paper", "research"]}, "public_route": {"type": "string", "nullable": true}, "content_hash": {"type": "string"}, "size_bytes": {"type": "integer"}, "current_version": {"type": "integer"}, "latest_version_id": {"type": "string", "nullable": true}, "created": {"type": "integer", "description": "Unix timestamp, in seconds."}, "updated": {"type": "integer", "description": "Unix timestamp, in seconds."}}},
  "MarkdownDocumentVersion": {"type": "object", "required": ["id", "document_id", "writer_customer_id", "ecosystem_id", "owner_kind", "owner_id", "version", "title", "content", "content_hash", "size_bytes", "created", "is_deleted"], "properties": {"id": {"type": "string"}, "document_id": {"type": "string"}, "writer_customer_id": {"type": "string", "description": "The revision WRITER."}, "deleted_at": {"type": "string", "nullable": true}, "ecosystem_id": {"type": "string"}, "owner_kind": {"type": "string", "enum": ["customer", "organization"], "description": "Inherited from the head document at write."}, "owner_id": {"type": "string", "description": "Inherited from the head document at write."}, "version": {"type": "integer"}, "title": {"type": "string", "description": "Document title at this revision (full-state snapshot)."}, "content": {"type": "string"}, "content_hash": {"type": "string"}, "size_bytes": {"type": "integer"}, "frontmatter": {"type": "object", "additionalProperties": true, "nullable": true}, "author_type": {"type": "string", "nullable": true}, "author_id": {"type": "string", "nullable": true}, "author_name": {"type": "string", "nullable": true}, "created": {"type": "integer", "description": "Unix timestamp, in seconds."}, "is_deleted": {"type": "boolean"}}},
