  "PublicPaperSearchHit": {"type": "object", "required": ["id", "title", "kind", "public_route", "author", "category", "tags", "summary", "evaluation", "snippet", "created", "updated"], "properties": {"id": {"type": "string"}, "title": {"type": "string"}, "kind": {"type": "string", "enum": ["paper", "research"], "description": "Document kind: 'paper' (ordinary) or 'research' (AI-ingested)."}, "public_route": {"type": "string", "description": "Published route slug; link as /public/users/{author.slug}/papers/{publicRoute}."}, "author": {"type": "object", "required": ["slug", "display_name"], "properties": {"slug": {"type": "string"}, "display_name": {"type": "string", "nullable": true}}}, "category": {"type": "string", "nullable": true}, "tags": {"type": "array", "items": {"type": "string"}}, "summary": {"type": "string", "nullable": true, "description": "Display summary read from the doc frontmatter (jsonb), or null."}, "evaluation": {"type": "string", "nullable": true, "description": "Display evaluation read from the doc frontmatter (jsonb), or null."}, "snippet": {"type": "string", "description": "~200-char match-context excerpt around the first q hit (head of content when q is empty/absent)."}, "created": {"type": "integer", "description": "Unix timestamp, in seconds."}, "updated": {"type": "integer", "description": "Unix timestamp, in seconds."}}},
  "PublicPaper": {"type": "object", "required": ["route", "title", "category", "tags", "content", "created", "updated"], "properties": {"route": {"type": "string"}, "title": {"type": "string"}, "category": {"type": "string", "nullable": true}, "tags": {"type": "array", "items": {"type": "string"}}, "content": {"type": "string", "description": "Full raw markdown, byte-exact."}, "created": {"type": "integer", "description": "Unix timestamp, in seconds."}, "updated": {"type": "integer", "description": "Unix timestamp, in seconds."}}},
  "PublicRegistrySummary": {"type": "object", "required": ["slug", "name", "purpose", "category_root", "tags"], "properties": {"slug": {"type": "string"}, "name": {"type": "string"}, "purpose": {"type": "string", "description": "One-line \"what this registry is for\"."}, "category_root": {"type": "string", "description": "The industry half of <industry>.<service-type>, e.g. 'software'."}, "tags": {"type": "array", "items": {"type": "string"}, "description": "The owner's discovery labels."}}},
  "PublicRegistryDirectory": {"type": "object", "required": ["items", "total", "page", "page_size"], "properties": {"items": {"type": "array", "items": {"$ref": "#/components/schemas/PublicRegistrySummary"}}, "total": {"type": "integer", "description": "Public registries in total, not just on this page — so a caller reading only page 1 can tell a short directory from a truncated one."}, "page": {"type": "integer"}, "page_size": {"type": "integer"}}},
  "PublicRegistrySection": {"type": "object", "required": ["key", "label", "description", "sort_order"], "properties": {"key": {"type": "string"}, "label": {"type": "string"}, "description": {"type": "string"}, "sort_order": {"type": "integer"}}},
