  "ShiprPersona": {"type": "object", "description": "A persona that may be put on a repository's crew. THREE FIELDS: the crew names an actor, it does not copy one — everything else about a persona is read where personas are read.", "properties": {"id": {"type": "string"}, "slug": {"type": "string"}, "name": {"type": "string"}}},
  "ShiprGroup": {"type": "object", "description": "A folder in the deployment tree. `path` and `depth` are trigger-maintained.", "properties": {"id": {"type": "string"}, "parent_id": {"type": "string", "nullable": true}, "name": {"type": "string"}, "path": {"type": "string"}, "depth": {"type": "integer"}, "position": {"type": "integer"}}},
  "ShiprRepo": {"type": "object", "description": "One deployment repository — a mirror. A dev repo with several `[deployments]` shards has one of these per shard.", "properties": {"id": {"type": "string"}, "dev_repo_id": {"type": "string"}, "group_id": {"type": "string", "nullable": true}, "slug": {"type": "string", "description": "owner/name on the forge."}, "shard": {"type": "string"}, "ship_branch": {"type": "string"}, "env_branches": {"type": "object", "additionalProperties": {"type": "string"}, "description": "environment → branch. An environment absent here is one this repository does not deploy to, and its ladder column is not drawn."}, "registered_at": {"type": "string", "nullable": true}, "provisioned": {"type": "object", "nullable": true}, "position": {"type": "integer"}}},
  "ShiprDevRepo": {"type": "object", "description": "The source repository a mirror is fed from.", "properties": {"id": {"type": "string"}, "slug": {"type": "string"}, "display_name": {"type": "string", "nullable": true, "description": "What the operator calls it, which is not always what the forge calls it. Null means no opinion and every reader falls back to `slug`. A LABEL AND NOTHING MORE: no branch, no path and no forge call is derived from it."}, "main_branch": {"type": "string"}, "prepared_branch": {"type": "string"}, "declaration_sha": {"type": "string", "nullable": true}, "connection_id": {"type": "string", "nullable": true}}},
  "ShiprOrgDefaults": {"type": "object", "description": "What a mirror in one forge org is BORN with — never a description of one that already exists. Read when a mirror is first written; changing it re-aims the next repository and moves nothing already registered.", "properties": {"id": {"type": "string"}, "org": {"type": "string", "description": "The forge account login."}, "deployment_owner": {"type": "string", "nullable": true, "description": "Which org the deployment repositories go in. Null is “the same org”, stored as null rather than as a copy so that an operator who never chose stays distinguishable from one who chose the org they were already in."}, "name_suffix": {"type": "string", "description": "`-deployment`, spelled per-org. Appended to the source repository’s name when its `.shipr` declares no shards."}, "env_branches": {"type": "object", "additionalProperties": {"type": "string"}, "description": "The ladder a new mirror starts with. Empty means the built-in default (every environment, named after itself), not a repository that deploys nowhere."}, "created": {"type": "integer", "description": "Unix timestamp, in seconds."}, "updated": {"type": "integer", "description": "Unix timestamp, in seconds."}}},
  "ShiprLadder": {"type": "object", "description": "The column-aligned commit view: one row per commit, oldest first, with a mark in each branch column whose tip is at or above it.", "properties": {"columns": {"type": "array", "items": {"type": "string"}}, "rows": {"type": "array", "items": {"type": "object", "properties": {"sha": {"type": "string"}, "when": {"type": "string"}, "subject": {"type": "string"}, "marks": {"type": "array", "items": {"type": "string"}}, "settled": {"type": "boolean"}}}}, "settled": {"type": "boolean", "description": "Every live branch is on the newest commit — nothing is in flight."}, "tips": {"type": "object", "additionalProperties": {"type": "string", "nullable": true}}, "notes": {"type": "array", "items": {"type": "string"}}, "read_at": {"type": "string", "description": "When the last status run read this."}}},
  "ShiprRun": {"type": "object", "description": "One queued or completed operation over a scope.", "properties": {"id": {"type": "string"}, "operation": {"type": "string", "enum": ["status", "prepare", "deploy", "register", "unregister"]}, "scope_kind": {"type": "string", "enum": ["deploy_repo", "dev_repo", "group", "all"]}, "scope_id": {"type": "string", "nullable": true}, "environments": {"type": "array", "items": {"type": "string"}}, "state": {"type": "string", "enum": ["queued", "running", "succeeded", "failed", "cancelled"]}, "summary": {"type": "object", "nullable": true}, "started_at": {"type": "string", "nullable": true}, "finished_at": {"type": "string", "nullable": true}, "created": {"type": "integer", "description": "Unix timestamp, in seconds."}}},
  "ShiprRunStep": {"type": "object", "description": "One repository within a run — and, for a deploy, one stage of it. A failed step does not fail the run.", "properties": {"id": {"type": "string"}, "run_id": {"type": "string"}, "deploy_repo_id": {"type": "string", "nullable": true}, "ordinal": {"type": "integer"}, "environment": {"type": "string", "nullable": true}, "stage": {"type": "string", "enum": ["advance", "arrival", "verify"], "nullable": true}, "state": {"type": "string", "enum": ["pending", "running", "succeeded", "failed", "skipped"]}, "detail": {"type": "object", "nullable": true}}},
  "ShiprRunEvent": {"type": "object", "description": "One line of a run’s log. `seq` is per-run and monotone — use it as a cursor.", "properties": {"seq": {"type": "integer"}, "step_id": {"type": "string", "nullable": true}, "stream": {"type": "string", "enum": ["out", "err", "meta"]}, "text": {"type": "string"}, "at": {"type": "string"}}},
  "FeedItem": {"type": "object", "required": ["id", "owner_kind", "owner_id", "ecosystem_id", "source", "entity_type", "action", "summary", "is_read", "created"], "properties": {"id": {"type": "string"}, "owner_kind": {"type": "string", "description": "Kind of principal that owns the feed item: 'customer', 'organization', 'application', 'persona' or 'ecosystem'."}, "owner_id": {"type": "string", "description": "Id of the owning principal."}, "author_kind": {"type": "string", "nullable": true, "enum": ["customer", "application", "persona"], "description": "Kind of principal that wrote the item; null when nobody did (a storage token)."}, "author_id": {"type": "string", "nullable": true, "description": "Id of that principal."}, "deleted_at": {"type": "string", "nullable": true}, "ecosystem_id": {"type": "string"}, "source": {"type": "string"}, "entity_type": {"type": "string"}, "entity_id": {"type": "string", "nullable": true}, "action": {"type": "string"}, "actor_id": {"type": "string", "nullable": true}, "summary": {"type": "string"}, "metadata": {"type": "string", "nullable": true}, "is_read": {"type": "boolean"}, "created": {"type": "integer", "description": "Unix timestamp, in seconds."}}},
  "FeedPage": {"type": "object", "required": ["items", "total", "page", "page_size"], "properties": {"items": {"type": "array", "items": {"$ref": "#/components/schemas/FeedItem"}}, "total": {"type": "integer"}, "page": {"type": "integer"}, "page_size": {"type": "integer"}}},
