  "AccessAuditEntry": {"type": "object", "required": ["id", "owner_kind", "owner_id", "actor_kind", "actor_id", "actor_email", "action", "subject_kind", "subject_id", "target_feature", "target_item_id", "role_id", "before", "after", "at"], "properties": {"id": {"type": "string"}, "owner_kind": {"type": "string"}, "owner_id": {"type": "string"}, "actor_kind": {"type": "string"}, "actor_id": {"type": "string"}, "actor_email": {"type": "string", "nullable": true}, "action": {"type": "string"}, "subject_kind": {"type": "string", "nullable": true}, "subject_id": {"type": "string", "nullable": true}, "target_feature": {"type": "string", "nullable": true}, "target_item_id": {"type": "string", "nullable": true}, "role_id": {"type": "string", "nullable": true}, "before": {"nullable": true, "description": "Pre-change state (action-shaped)"}, "after": {"nullable": true, "description": "Post-change state (action-shaped)"}, "at": {"type": "string"}}},
  "AccessAuditPage": {"type": "object", "required": ["items", "page", "page_size", "total"], "properties": {"items": {"type": "array", "items": {"$ref": "#/components/schemas/AccessAuditEntry"}}, "page": {"type": "integer"}, "page_size": {"type": "integer", "description": "Clamped 1..200"}, "total": {"type": "integer", "description": "Saturates at a 10,000-row count cap"}}},
  "ReservedIdentifier": {"type": "object", "required": ["rdid", "entity_type", "entity_id", "reason", "held_since", "releasable", "needs_name"], "properties": {"rdid": {"type": "string"}, "entity_type": {"type": "string"}, "entity_id": {"type": "string"}, "reason": {"type": "string", "enum": ["rename-leftover", "orphan", "deleted-entity"], "description": "What is holding the name. An in-window rename alias and an orphaned mapping are deleted outright. A deleted entity is freed the same way when its own table has already let the name go; while that table is still holding it, the release renames that row instead and `needsName` is true."}, "held_since": {"type": "string", "nullable": true, "description": "When the name got stuck: an alias's supersede instant, else the row's last write"}, "releasable": {"type": "boolean", "description": "False for names this surface can only report: a revoked token slug (reserved by policy) and legacy reverse-domain handles with no parent chain. Releasing a non-releasable row answers 403."}, "needs_name": {"type": "boolean", "description": "Releasing this one needs a name from you. The deleted row is still sitting on the slug in its own table, so freeing it is a rename, and this service does not invent names — send it as `newNames[rdid]` on the release."}}},
  "ReservedIdentifierPage": {"type": "object", "required": ["items", "page", "page_size", "total", "truncated"], "properties": {"items": {"type": "array", "items": {"$ref": "#/components/schemas/ReservedIdentifier"}}, "page": {"type": "integer"}, "page_size": {"type": "integer", "description": "Clamped 1..200"}, "total": {"type": "integer", "description": "Saturates at a 2,000-row cap: the list merges heterogeneous sources and cannot be paged by a single SQL OFFSET"}, "truncated": {"type": "boolean", "description": "A held name is missing from this response — a source scan came back at its cap, or the merge overflowed the overall one. Clients that filter client-side MUST surface this: past the cap an empty result is not evidence that a name is free."}}},
  "ReleasedName": {"type": "object", "required": ["rdid", "reason", "freed", "aliases_removed", "still_held_by", "renamed_to"], "properties": {"rdid": {"type": "string"}, "reason": {"type": "string", "enum": ["rename-leftover", "orphan", "deleted-entity"]}, "freed": {"type": "boolean", "description": "The released NAME is available again. Deliberately not \"the surrounding namespace is empty\" — a different type sharing that path is a different name."}, "aliases_removed": {"type": "integer"}, "still_held_by": {"type": "array", "items": {"type": "string"}, "description": "Canonical addresses still sitting in that space, informational. Read as \"these exist nearby\", never as \"the release failed\"."}, "renamed_to": {"type": "string", "nullable": true, "description": "The name the dead row was renamed to — your own `newNames` entry, echoed back. Null on every other branch, where nothing outside the identifier table was written."}}},
  "ReleaseResult": {"allOf": [{"$ref": "#/components/schemas/ReleasedName"}, {"type": "object", "required": ["children"], "properties": {"children": {"type": "array", "items": {"$ref": "#/components/schemas/ReleasedName"}}}}]},
  "AdminNote": {"type": "object", "description": "An operator note attached to some other row. Never visible to that row’s subject.", "required": ["id", "ecosystem_id", "subject_table", "subject_id", "content", "created_by", "created", "updated"], "properties": {"id": {"type": "string", "maxLength": 36}, "ecosystem_id": {"type": "string", "maxLength": 36}, "subject_table": {"type": "string", "maxLength": 120}, "subject_id": {"type": "string", "maxLength": 36}, "content": {"type": "string"}, "created_by": {"type": "string", "maxLength": 36}, "created": {"type": "integer", "description": "Unix timestamp, in seconds."}, "updated": {"type": "integer", "description": "Unix timestamp, in seconds."}}},
