  "AdminNoteInput": {"type": "object", "required": ["content"], "properties": {"id": {"type": "string", "maxLength": 36, "description": "Omit to create; supply to update in place"}, "content": {"type": "string", "minLength": 1}}},
  "EntityHistoryEntry": {"type": "object", "description": "One thing that happened to a row. Append-only; nothing here is editable.", "required": ["id", "ecosystem_id", "subject_table", "subject_id", "actor_id", "actor_label", "action", "detail", "created"], "properties": {"id": {"type": "string", "maxLength": 36}, "ecosystem_id": {"type": "string", "maxLength": 36}, "subject_table": {"type": "string", "maxLength": 120}, "subject_id": {"type": "string", "maxLength": 36}, "actor_id": {"type": "string", "maxLength": 36, "nullable": true}, "actor_label": {"type": "string", "maxLength": 120, "nullable": true}, "action": {"type": "string", "maxLength": 60, "description": "Free text, not an enum — each subsystem names its own. Emitted today: request_received, invite_sent, note_added, status_changed, accepted, notes_updated."}, "detail": {"type": "object", "additionalProperties": true, "nullable": true, "description": "Action-specific payload; the shape is whatever emitted the entry."}, "created": {"type": "integer", "description": "Unix timestamp, in seconds."}}},
  "TeamMember": {"type": "object", "required": ["id", "team_id", "member_kind", "user_id", "role", "added_at"], "properties": {"id": {"type": "string"}, "team_id": {"type": "string"}, "member_kind": {"type": "string", "enum": ["customer", "persona"], "description": "which principal userId names — 'customer' (customer.customers) or 'persona' (persona.personas). Present on every response: GET list rows, the add-persona 201, and the by-email add 201 (always a customer)."}, "user_id": {"type": "string", "description": "the member principal id — a customer id, or a persona id when memberKind is 'persona'"}, "role": {"type": "string"}, "added_at": {"type": "string"}, "email": {"type": "string", "nullable": true, "description": "the member's email (resolved; null for a persona member or a foreign customer)"}, "display_name": {"type": "string", "nullable": true}, "persona_slug": {"type": "string", "nullable": true, "description": "the persona's slug when memberKind is 'persona' (null for a customer member)"}, "persona_name": {"type": "string", "nullable": true}}},
