  "AccessFeature": {"type": "object", "required": ["key", "label"], "properties": {"key": {"type": "string", "description": "the feature-area key grants are recorded against, e.g. 'audiences'"}, "label": {"type": "string", "description": "the display name for this area (the roles editor labels its row with it)"}}},
