  "AccessRole": {"type": "object", "required": ["id", "slug", "name", "description", "is_system", "default_for", "grants"], "properties": {"id": {"type": "string"}, "slug": {"type": "string"}, "name": {"type": "string"}, "description": {"type": "string"}, "is_system": {"type": "boolean"}, "default_for": {"type": "string", "enum": ["", "customer", "persona"], "description": "which member kind holds this role implicitly as the workspace default"}, "grants": {"type": "array", "items": {"$ref": "#/components/schemas/AccessGrant"}}}},
