  "AccessAssignmentList": {"type": "object", "required": ["assignments"], "properties": {"assignments": {"type": "array", "items": {"$ref": "#/components/schemas/AccessAssignment"}}, "restricted": {"type": "boolean", "description": "present on item-scoped listings: whether the item is RESTRICTED"}}},
