  "StorageAttachment": {"type": "object", "required": ["id", "ecosystem_id", "owner_kind", "owner_id", "parent_type", "object_key", "storage_kind", "filename", "content_type", "size_bytes", "content_hash", "status", "created", "updated"], "properties": {"id": {"type": "string"}, "ecosystem_id": {"type": "string"}, "owner_kind": {"type": "string", "description": "Kind of principal that owns the attachment: 'customer', 'organization', 'application', 'persona' or 'ecosystem'."}, "owner_id": {"type": "string", "description": "Id of the owning principal."}, "parent_type": {"type": "string", "description": "Kind of row the attachment hangs off, e.g. 'standalone', 'persona', 'registry.entry'."}, "parent_id": {"type": "string", "nullable": true, "description": "Id of the row the attachment hangs off; null for a standalone attachment."}, "object_key": {"type": "string", "description": "R2 object key the presigned URLs address."}, "storage_kind": {"type": "string", "description": "Backing store, e.g. 'r2'."}, "filename": {"type": "string"}, "content_type": {"type": "string"}, "size_bytes": {"type": "integer"}, "content_hash": {"type": "string"}, "width": {"type": "integer", "nullable": true}, "height": {"type": "integer", "nullable": true}, "duration_ms": {"type": "integer", "nullable": true}, "status": {"type": "string", "enum": ["pending", "ready"], "description": "'pending' (presigned, awaiting upload) → 'ready' (bytes confirmed)."}, "metadata": {"type": "object", "additionalProperties": true, "nullable": true, "description": "Caller-supplied JSON metadata (jsonb) — intentionally open."}, "created": {"type": "integer", "description": "Unix timestamp, in seconds."}, "updated": {"type": "integer", "description": "Unix timestamp, in seconds."}, "deleted_at": {"type": "string", "nullable": true}}},
