  "GET /v1/ownership/items": {"key": "GET /v1/ownership/items", "method": "GET", "path": "/v1/ownership/items", "tag": "ecosystem", "summary": "What a customer, organization, persona or ecosystem still owns", "params": [{"name": "kind", "in": "query", "required": true, "schema": {"type": "string", "enum": ["customer", "organization", "application", "persona", "ecosystem"]}}, {"name": "id", "in": "query", "required": true, "schema": {"type": "string"}}, {"name": "expand[]", "in": "query", "required": false, "schema": {"type": "array", "items": {"type": "string"}}, "description": "Related objects to return in full instead of as an id. Up to four levels, e.g. `ecosystem_id`; on a list, `data.<field>`."}], "description": "Replaces GET /ownership/owned.", "responses": [{"status": "200", "description": "The tables it owns rows in, with counts", "contentType": "application/json", "schema": {"type": "object", "properties": {"object": {"type": "string", "const": "ownership.item"}, "kind": {"type": "string", "enum": ["customer", "organization", "application", "persona", "ecosystem"]}, "id": {"type": "string"}, "owned": {"type": "array", "items": {"type": "object", "required": ["table", "rows"], "properties": {"table": {"type": "string", "description": "`<schema>.<table>`"}, "rows": {"type": "integer"}}}}}}}, {"status": "400", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "403", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "404", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}], "security": ["bearerAuth"], "family": ["GET /v1/ownership/items", "POST /v1/ownership/erasures", "POST /v1/ownership/handovers", "POST /v1/ownership/transfers"]},
