  "GET /v1/projects/{id}/milestones": {"key": "GET /v1/projects/{id}/milestones", "method": "GET", "path": "/v1/projects/{id}/milestones", "tag": "project", "summary": "List a project's milestones, each with its live card counts", "params": [{"name": "id", "in": "path", "required": true, "schema": {"type": "string"}}, {"name": "limit", "in": "query", "required": false, "schema": {"type": "integer", "minimum": 1, "maximum": 100, "default": 10}, "description": "Page size, 1–100 (default 10)."}, {"name": "starting_after", "in": "query", "required": false, "schema": {"type": "string"}, "description": "Cursor: an object id; returns the page after it."}, {"name": "ending_before", "in": "query", "required": false, "schema": {"type": "string"}, "description": "Cursor: an object id; returns the page before it."}, {"name": "expand[]", "in": "query", "required": false, "schema": {"type": "array", "items": {"type": "string"}}, "description": "Related objects to return in full instead of as an id. Up to four levels, e.g. `ecosystem_id`; on a list, `data.<field>`."}], "description": "Plan order — by targetDate ascending, with the UNDATED last. An undated milestone is the one a reader most needs to find at a predictable end of the list, so where it lands is part of the contract rather than a default anyone should have to discover.\n\nReplaces GET /project/projects/{id}/milestones.", "responses": [{"status": "200", "description": "Milestones", "contentType": "application/json", "schema": {"type": "object", "required": ["object", "data", "has_more", "url"], "properties": {"object": {"type": "string", "const": "list"}, "data": {"type": "array", "items": {"allOf": [{"type": "object", "properties": {"object": {"type": "string", "const": "milestone"}}}, {"$ref": "#/components/schemas/ProjectMilestone"}]}}, "has_more": {"type": "boolean"}, "url": {"type": "string"}}}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "404", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}], "security": ["bearerAuth"], "family": ["DELETE /v1/projects/{id}/milestones/{milestone_id}", "GET /v1/projects/{id}/milestones", "POST /v1/projects/{id}/milestones", "POST /v1/projects/{id}/milestones/{milestone_id}"]},
  "GET /v1/projects/{id}/participants": {"key": "GET /v1/projects/{id}/participants", "method": "GET", "path": "/v1/projects/{id}/participants", "tag": "project", "summary": "List a project's participants (by addedAt)", "params": [{"name": "id", "in": "path", "required": true, "schema": {"type": "string"}}, {"name": "limit", "in": "query", "required": false, "schema": {"type": "integer", "minimum": 1, "maximum": 100, "default": 10}, "description": "Page size, 1–100 (default 10)."}, {"name": "starting_after", "in": "query", "required": false, "schema": {"type": "string"}, "description": "Cursor: an object id; returns the page after it."}, {"name": "ending_before", "in": "query", "required": false, "schema": {"type": "string"}, "description": "Cursor: an object id; returns the page before it."}, {"name": "expand[]", "in": "query", "required": false, "schema": {"type": "array", "items": {"type": "string"}}, "description": "Related objects to return in full instead of as an id. Up to four levels, e.g. `ecosystem_id`; on a list, `data.<field>`."}], "description": "Replaces GET /project/projects/{id}/participants.", "responses": [{"status": "200", "description": "Participants", "contentType": "application/json", "schema": {"type": "object", "required": ["object", "data", "has_more", "url"], "properties": {"object": {"type": "string", "const": "list"}, "data": {"type": "array", "items": {"allOf": [{"type": "object", "properties": {"object": {"type": "string", "const": "participant"}}}, {"$ref": "#/components/schemas/ProjectParticipant"}]}}, "has_more": {"type": "boolean"}, "url": {"type": "string"}}}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "404", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}], "security": ["bearerAuth"], "family": ["DELETE /v1/projects/{id}/participants/{participant_id}", "GET /v1/projects/{id}/participants", "POST /v1/projects/{id}/participants"]},
