  "GET /v1/projects/{id}/statuses": {"key": "GET /v1/projects/{id}/statuses", "method": "GET", "path": "/v1/projects/{id}/statuses", "tag": "project", "summary": "List a project's board columns (by position)", "params": [{"name": "id", "in": "path", "required": true, "schema": {"type": "string"}}, {"name": "limit", "in": "query", "required": false, "schema": {"type": "integer", "minimum": 1, "maximum": 100, "default": 10}, "description": "Page size, 1–100 (default 10)."}, {"name": "starting_after", "in": "query", "required": false, "schema": {"type": "string"}, "description": "Cursor: an object id; returns the page after it."}, {"name": "ending_before", "in": "query", "required": false, "schema": {"type": "string"}, "description": "Cursor: an object id; returns the page before it."}, {"name": "expand[]", "in": "query", "required": false, "schema": {"type": "array", "items": {"type": "string"}}, "description": "Related objects to return in full instead of as an id. Up to four levels, e.g. `ecosystem_id`; on a list, `data.<field>`."}], "description": "Replaces GET /project/projects/{id}/statuses.", "responses": [{"status": "200", "description": "Statuses", "contentType": "application/json", "schema": {"type": "object", "required": ["object", "data", "has_more", "url"], "properties": {"object": {"type": "string", "const": "list"}, "data": {"type": "array", "items": {"allOf": [{"type": "object", "properties": {"object": {"type": "string", "const": "statuse"}}}, {"$ref": "#/components/schemas/ProjectStatus"}]}}, "has_more": {"type": "boolean"}, "url": {"type": "string"}}}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "404", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}], "security": ["bearerAuth"], "family": ["DELETE /v1/projects/{id}/statuses/{status_id}", "GET /v1/projects/{id}/statuses", "POST /v1/projects/{id}/statuses", "POST /v1/projects/{id}/statuses/{status_id}"]},
  "GET /v1/projects/{id}/stream": {"key": "GET /v1/projects/{id}/stream", "method": "GET", "path": "/v1/projects/{id}/stream", "tag": "project", "summary": "Server-sent wake stream for one board", "params": [{"name": "id", "in": "path", "required": true, "schema": {"type": "string"}}, {"name": "expand[]", "in": "query", "required": false, "schema": {"type": "array", "items": {"type": "string"}}, "description": "Related objects to return in full instead of as an id. Up to four levels, e.g. `ecosystem_id`; on a list, `data.<field>`."}], "description": "Opens an SSE stream that emits a payload-less `project` event ({}) each time anything on this board changes, so an open client refetches through the ordinary routes it already uses. The event deliberately carries NO data and NO kind: the stream is held open outside any tenant transaction, so the sending side has no caller to authorize a row against — a wake that carries nothing cannot leak anything. Several changes made by one gesture arrive as ONE event. Closes after 5 minutes; reconnect. When the server has no push channel configured it emits a single `ready` event instead and closes, and the client falls back to polling. Reachability is checked before the stream opens (404 for a board the caller cannot read), and — uniquely among Projects routes — the access token may be passed as `?access_token=`, because a browser EventSource cannot set the Authorization header.\n\nReplaces GET /project/projects/{id}/stream.", "responses": [{"status": "200", "description": "text/event-stream of payload-less board wake events", "contentType": "application/json", "schema": {"type": "object", "properties": {"object": {"type": "string", "const": "project"}}}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "403", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "404", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}], "security": ["bearerAuth"], "family": ["DELETE /v1/projects/{id}", "DELETE /v1/projects/{id}/research", "GET /v1/projects", "GET /v1/projects/{id}", "GET /v1/projects/{id}/activity", "GET /v1/projects/{id}/stream", "POST /v1/projects", "POST /v1/projects/{id}", "POST /v1/projects/{id}/research"]},
