  "POST /v1/auth/methods/{method}": {"key": "POST /v1/auth/methods/{method}", "method": "POST", "path": "/v1/auth/methods/{method}", "tag": "auth", "summary": "Enable or disable an auth method setting, upserting it (admin)", "params": [{"name": "method", "in": "path", "required": true, "schema": {"type": "string"}}], "description": "Replaces PATCH /auth/methods/{method}.", "requestBody": {"required": true, "contentType": "application/json", "schema": {"type": "object", "required": ["enabled"], "properties": {"enabled": {"type": "boolean"}}}}, "responses": [{"status": "200", "description": "upserted setting", "contentType": "application/json", "schema": {"allOf": [{"type": "object", "properties": {"object": {"type": "string", "const": "auth.method"}}}, {"$ref": "#/components/schemas/AuthMethodSetting"}]}}, {"status": "400", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "403", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}], "security": ["bearerAuth"], "family": ["DELETE /v1/auth/methods/{method}", "GET /v1/auth/methods", "GET /v1/auth/methods/{method}", "POST /v1/auth/methods", "POST /v1/auth/methods/{method}"]},
  "POST /v1/auth/passkey_challenges": {"key": "POST /v1/auth/passkey_challenges", "method": "POST", "path": "/v1/auth/passkey_challenges", "tag": "auth", "summary": "WebAuthn 2nd-factor: assertion options bound to the pending challenge", "params": [], "description": "Replaces POST /auth/login/mfa/webauthn/options, POST /auth/login/webauthn/options.", "requestBody": {"required": true, "contentType": "application/json", "schema": {"allOf": [{"oneOf": [{"type": "object", "required": ["token"], "properties": {"token": {"type": "string", "description": "MFA pending token"}}}, {"type": "object", "required": ["identifier"], "properties": {"identifier": {"type": "string", "description": "Email or login slug"}}}]}, {"type": "object", "properties": {"method": {"type": "string", "enum": ["mfa_passkey", "passkey"], "description": "Selects which kind of object this call works on."}}, "required": ["method"]}]}}, "responses": [{"status": "200", "description": "options + next pending token", "contentType": "application/json", "schema": {"type": "object", "required": ["options", "token"], "properties": {"object": {"type": "string", "const": "auth.passkey_challenge"}, "options": {"type": "object", "additionalProperties": true, "description": "PublicKeyCredentialRequestOptionsJSON"}, "token": {"type": "string"}}}}, {"status": "400", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "422", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}], "family": ["GET /v1/auth/capabilities", "POST /v1/auth/passkey_challenges", "POST /v1/auth/registrations", "POST /v1/auth/sessions", "POST /v1/auth/sms_codes"]},
