  "POST /v1/personas/{id}/actors": {"key": "POST /v1/personas/{id}/actors", "method": "POST", "path": "/v1/personas/{id}/actors", "tag": "registry", "summary": "Grant a may_act subject kind (user/team/org) to a persona (owner/admin)", "params": [{"name": "id", "in": "path", "required": true, "schema": {"type": "string"}}], "description": "Replaces POST /access/personas/{id}/may-act.", "requestBody": {"required": true, "contentType": "application/json", "schema": {"type": "object", "required": ["kind"], "properties": {"kind": {"type": "string", "enum": ["user", "team", "org"]}}}}, "responses": [{"status": "200", "description": "the granted subject kinds after the grant", "contentType": "application/json", "schema": {"allOf": [{"type": "object", "properties": {"object": {"type": "string", "const": "actor"}}}, {"$ref": "#/components/schemas/RegistryPersonaMayAct"}]}}, {"status": "400", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "403", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "404", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}], "security": ["bearerAuth"], "family": ["DELETE /v1/personas/{id}/actors/{kind}", "GET /v1/personas/{id}/actors", "POST /v1/personas/{id}/actors"]},
  "POST /v1/personas/{id}/tokens": {"key": "POST /v1/personas/{id}/tokens", "method": "POST", "path": "/v1/personas/{id}/tokens", "tag": "registry", "summary": "Mint a scoped API token that lets the persona act (raw value shown once)", "params": [{"name": "id", "in": "path", "required": true, "schema": {"type": "string"}}], "description": "Replaces POST /persona/personas/{id}/tokens.", "requestBody": {"required": true, "contentType": "application/json", "schema": {"type": "object", "required": ["subject"], "properties": {"subject": {"type": "object", "required": ["kind"], "properties": {"kind": {"type": "string", "enum": ["self", "user", "team", "org"], "description": "`self` (owner-gated) or `user` (the caller lets the persona act AS themselves, gated on the persona’s `may_act user` opt-in) or `team` (owner-gated; the persona acts AS the team `id` in the target `ecosystemId`, gated on `may_act team` + persona team-membership + the team’s reach into that ecosystem) or `org` (owner-gated; the persona acts AS the organization `id` it is OWNED BY, gated on `may_act org` + org-ownership; the acting ecosystem is the org’s own, derived server-side)."}, "id": {"type": "string", "description": "The team id for a `team` subject (required for `team`) or the org id for an `org` subject (required for `org`). Ignored for `self` (derived from the persona) and `user` (always the authenticated caller, never a param)."}, "ecosystem_id": {"type": "string", "description": "The TARGET ecosystem a `team` subject acts in (required for `team`); ignored for the other kinds (an `org` subject’s ecosystem is derived from the org, never taken from the request)."}}}, "name": {"type": "string", "minLength": 1, "maxLength": 100}, "expires_at": {"type": "string", "format": "date-time", "nullable": true, "description": "Omitted/null defaults to a bounded 90-day TTL (never a non-expiring token); an explicit value is honored."}}}}, "responses": [{"status": "201", "description": "the minted token metadata + its raw value (shown once)", "contentType": "application/json", "schema": {"allOf": [{"type": "object", "properties": {"object": {"type": "string", "const": "token"}}}, {"$ref": "#/components/schemas/RegistryPersonaTokenCreated"}]}}, {"status": "400", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "403", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "404", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}, {"status": "409", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/StripeError"}}], "security": ["bearerAuth"], "family": ["DELETE /v1/personas/{id}/tokens/{token_id}", "GET /v1/personas/{id}/tokens", "POST /v1/personas/{id}/tokens"]},
